// A autoria/publicação não tem tela (ver `real/versoes-servidor`); aqui valida-se só a leitura:
// Versões, Composição e o resumo de movimentações do painel, com a resposta da API stubada.

const ID = 'cart-1'
const ativo = (n: number, ticker: string, nome: string, peso: number) => ({
  id: `i${n}`,
  ativoId: `a${n}`,
  tickerCodigo: ticker,
  nomeAtivo: nome,
  classeAtivo: 'Ações',
  pesoPercentual: peso,
  statusMovimentacao: 'MANTER',
})

const CARTEIRA = {
  id: ID,
  nome: 'Carteira Moderada',
  perfilAlvo: 'MODERADO',
  descricao: null,
  ativa: true,
  criadoEm: '2026-01-01T00:00:00.000Z',
  versaoAtual: {
    id: 'v-out',
    mesReferencia: '2026-10',
    publicada: true,
    publicadaEm: '2026-10-05T12:00:00.000Z',
    itens: [ativo(1, 'ITUB4', 'Itaú Unibanco', 70), ativo(3, 'VALE3', 'Vale', 30)],
  },
}

const VERSOES = [
  {
    id: 'v-out',
    mesReferencia: '2026-10',
    publicada: true,
    publicadaEm: '2026-10-05T12:00:00.000Z',
    totalItens: 3,
  },
  {
    id: 'v-set',
    mesReferencia: '2026-09',
    publicada: true,
    publicadaEm: '2026-09-04T12:00:00.000Z',
    totalItens: 2,
  },
  { id: 'v-nov', mesReferencia: '2026-11', publicada: false, publicadaEm: null, totalItens: 4 },
]

describe('Plano QA · Composição e versões (UI)', () => {
  beforeEach(() => {
    cy.bloquearApi()
  })

  it('VER 01/03/05/06 · admin abre Versões e Composição → rascunho e publicadas distintos, vigente correta e nenhum controle de edição', () => {
    cy.stubSessao('admin')
    cy.stubApi('GET', `/carteiras/${ID}`, CARTEIRA, 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${ID}/versoes*`,
      { items: VERSOES, total: 3, page: 1, pageSize: 100 },
      'versoes',
    )

    cy.visit(`/admin/carteiras/${ID}`)
    cy.wait(['@detalhe', '@versoes'])

    // Composição vigente: M publicada, pesos e total fechando 100.
    cy.contains('Versão vigente').should('contain.text', 'Outubro')
    cy.contains('Publicada').should('be.visible')
    cy.contains('li', 'Itaú Unibanco').should('contain.text', '70,00 %')
    cy.contains('li', 'Vale').should('contain.text', '30,00 %')
    cy.contains('Total').parent().should('contain.text', '100,00 %')
    // O rascunho de novembro não é a vigente.
    cy.contains('Novembro').should('not.exist')

    cy.contains('[role="tab"]', 'Versões').click()
    cy.get('tbody tr').should('have.length', 3)
    cy.contains('tr', 'Outubro')
      .should('contain.text', 'Publicada')
      .and('contain.text', '3 ativos')
      .and('contain.text', '05/10/2026')
    cy.contains('tr', 'Setembro')
      .should('contain.text', 'Publicada')
      .and('contain.text', '2 ativos')
      .and('contain.text', '04/09/2026')
    cy.contains('tr', 'Novembro')
      .should('contain.text', 'Rascunho')
      .and('contain.text', '4 ativos')
      .and('contain.text', '—')

    // Publicadas são somente leitura: sem Editar, Remover, Publicar nem Adicionar ativo.
    cy.contains('button, a', /editar|remover|excluir|publicar|adicionar ativo/i).should('not.exist')
  })

  it('VER 08 · painel com entrada, saída e mudança de peso → resumo e lista do mês batem com as movimentações', () => {
    cy.intercept('GET', '**/api/v1/auth/me', {
      id: '11111111-1111-4111-8111-111111111111',
      nome: 'Maria Teste',
      email: 'maria@teste.com',
      perfil: 'cliente',
      perfilInvestidor: 'MODERADO',
      carteiraVinculada: { id: ID, nome: CARTEIRA.nome, perfilAlvo: 'MODERADO' },
    }).as('me')
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: 'Maria Teste', perfilInvestidor: 'MODERADO' },
        suitabilityRealizado: true,
        suitabilityVencido: false,
        carteira: { id: ID, nome: CARTEIRA.nome, totalAtivos: 2, rentabilidadeUltimoMes: 1.5 },
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 1, saidas: 1 },
      },
      'dashboard',
    )
    cy.stubApi(
      'GET',
      '/minha-carteira/performance',
      {
        carteiraNome: CARTEIRA.nome,
        mesAtual: null,
        acumuladoAno: { rentabilidade: 0, cdi: 0 },
        historicoUltimosMeses: [],
      },
      'performance',
    )
    cy.stubApi('GET', `/carteiras/${ID}`, CARTEIRA, 'detalhe')
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [], total: 0, page: 1, pageSize: 1 },
      'relatorios',
    )
    cy.stubApi(
      'GET',
      `/carteiras/${ID}/movimentacoes*`,
      {
        carteiraId: ID,
        mesReferencia: '2026-10',
        movimentacoes: {
          entradas: [{ ticker: 'VALE3', nome: 'Vale', pesoAtual: 30, justificativa: null }],
          saidas: [{ ticker: 'PETR4', nome: 'Petrobras', pesoAnterior: 50, justificativa: null }],
          alteracoes: [
            {
              ticker: 'ITUB4',
              nome: 'Itaú Unibanco',
              pesoAnterior: 50,
              pesoAtual: 70,
              tipo: 'AUMENTOU',
            },
          ],
          mantidos: [],
        },
      },
      'movimentacoes',
    )

    cy.visit('/')
    cy.wait('@movimentacoes')
    cy.contains('A revisão de').should('contain.text', 'trocou 2 ativos e ajustou 1 peso')

    cy.contains('h2', 'Movimentações do mês')
      .closest('[data-slot="card"]')
      .within(() => {
        cy.contains('li', 'VALE3').should('contain.text', 'Entrou')
        cy.contains('li', 'PETR4').should('contain.text', 'Saiu')
        cy.contains('li', 'ITUB4').should('contain.text', 'Aumentou')
        cy.get('li').should('have.length', 3)
      })
  })

  it('VER 08 · mês sem alterações → o painel diz que a composição foi mantida e não lista movimentos', () => {
    cy.intercept('GET', '**/api/v1/auth/me', {
      id: '11111111-1111-4111-8111-111111111111',
      nome: 'Maria Teste',
      email: 'maria@teste.com',
      perfil: 'cliente',
      perfilInvestidor: 'MODERADO',
      carteiraVinculada: { id: ID, nome: CARTEIRA.nome, perfilAlvo: 'MODERADO' },
    }).as('me')
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: 'Maria Teste', perfilInvestidor: 'MODERADO' },
        suitabilityRealizado: true,
        suitabilityVencido: false,
        carteira: { id: ID, nome: CARTEIRA.nome, totalAtivos: 2, rentabilidadeUltimoMes: 1.5 },
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 0, saidas: 0 },
      },
      'dashboard',
    )
    cy.stubErroApi(
      'GET',
      '/minha-carteira/performance',
      { status: 422, code: 'SUITABILITY_PENDENTE', message: 'x' },
      'performance',
    )
    cy.stubApi('GET', `/carteiras/${ID}`, CARTEIRA, 'detalhe')
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [], total: 0, page: 1, pageSize: 1 },
      'relatorios',
    )
    cy.stubApi(
      'GET',
      `/carteiras/${ID}/movimentacoes*`,
      {
        carteiraId: ID,
        mesReferencia: '2026-10',
        movimentacoes: {
          entradas: [],
          saidas: [],
          alteracoes: [],
          mantidos: [{ ticker: 'ITUB4', nome: 'Itaú Unibanco', peso: 100 }],
        },
      },
      'movimentacoes',
    )

    cy.visit('/')
    cy.wait('@movimentacoes')
    cy.contains('manteve a composição sem alterações').should('be.visible')
    cy.contains('Nenhuma movimentação nesta competência.').should('be.visible')
  })
})

export {}
